<?php
require_once __DIR__.'/includes/bootstrap.php';require_login();$pdo=db();$today=date('Y-m-d');
$q=$pdo->prepare("SELECT COALESCE(SUM(total),0) FROM sales WHERE DATE(created_at)=? AND status='completed'");$q->execute([$today]);$salesToday=$q->fetchColumn();
$q=$pdo->prepare("SELECT COUNT(*) FROM sales WHERE DATE(created_at)=? AND status='completed'");$q->execute([$today]);$countToday=$q->fetchColumn();
$q=$pdo->query("SELECT COALESCE(SUM(quantity_on_hand<=reorder_level),0) FROM stock_items");$lowStock=$q->fetchColumn();
$q=$pdo->query("SELECT COALESCE(SUM(amount),0) FROM expenses WHERE DATE(expense_date)=CURDATE()");$expensesToday=$q->fetchColumn();
$recent=$pdo->query("SELECT s.*,u.full_name FROM sales s JOIN users u ON u.id=s.cashier_id ORDER BY s.id DESC LIMIT 7")->fetchAll();
$top=$pdo->query("SELECT product_name,SUM(quantity) qty FROM sale_items si JOIN sales s ON s.id=si.sale_id WHERE s.status='completed' AND DATE(s.created_at)=CURDATE() GROUP BY product_name ORDER BY qty DESC LIMIT 5")->fetchAll();
$pageTitle='Dashboard';require 'includes/header.php';?>
<div class="welcome-row"><div><h1>Good <?=date('H')<12?'morning':(date('H')<17?'afternoon':'evening')?>, <?=e(explode(' ',$_SESSION['user']['full_name'])[0])?>.</h1><p class="muted">Here is what's happening at your restaurant today.</p></div><a class="btn primary" href="pos.php">＋ Start a sale</a></div>
<div class="stats-grid"><div class="stat-card"><span class="stat-icon blue">＄</span><small>Today's sales</small><strong><?=money($salesToday)?></strong><em>Completed transactions</em></div><div class="stat-card"><span class="stat-icon purple">▤</span><small>Transactions today</small><strong><?=number_format($countToday)?></strong><em>Sales completed</em></div><div class="stat-card"><span class="stat-icon orange">▣</span><small>Low stock items</small><strong><?=number_format($lowStock)?></strong><em>At or below reorder level</em></div><div class="stat-card"><span class="stat-icon green">＄</span><small>Today's expenses</small><strong><?=money($expensesToday)?></strong><em>Recorded expenses</em></div></div>
<div class="two-col"><div class="panel"><div class="panel-head"><div><h3>Recent sales</h3><p class="muted">Latest completed transactions</p></div><a href="sales.php" class="text-link">View all</a></div><div class="table-wrap"><table><thead><tr><th>Receipt</th><th>Cashier</th><th>Date</th><th>Total</th></tr></thead><tbody><?php foreach($recent as $r):?><tr><td><a href="receipt.php?id=<?=$r['id']?>" class="text-link"><?=e($r['receipt_number'])?></a></td><td><?=e($r['full_name'])?></td><td><?=date('d M, H:i',strtotime($r['created_at']))?></td><td><b><?=money($r['total'])?></b></td></tr><?php endforeach;?><?php if(!$recent):?><tr><td colspan="4" class="empty">No sales recorded yet.</td></tr><?php endif;?></tbody></table></div></div><div class="panel"><div class="panel-head"><div><h3>Popular today</h3><p class="muted">Items sold by quantity</p></div></div><?php foreach($top as $t):?><div class="popular-row"><span><?=e($t['product_name'])?></span><b><?=number_format($t['qty'],0)?> sold</b></div><?php endforeach;?><?php if(!$top):?><p class="empty">Product activity will appear here after sales.</p><?php endif;?></div></div>
<?php require 'includes/footer.php';?>
